import 'package:cephalopod/features/game/domain/models/opponent.dart';
import 'package:cephalopod/features/game/presentation/bloc/turn_phase.dart';
import 'package:cephalopod_engine/cephalopod_engine.dart';
import 'package:freezed_annotation/freezed_annotation.dart';

part 'game_view_state.freezed.dart';

/// Everything the game screen renders: the engine's [game], what the screen
/// is waiting for ([phase]), the [lastMove], to highlight it, whether a move
/// can be taken back ([canUndo]) or played again ([canRedo]), and the
/// [opponent], to name the sides.
///
/// Plain data generated by freezed: value equality, `copyWith` and
/// `toString`, with no behaviour (docs/adr/0011).
@freezed
abstract class GameViewState with _$GameViewState {
  const factory GameViewState({
    required GameState game,
    required TurnPhase phase,
    Move? lastMove,
    @Default(false) bool canUndo,
    @Default(false) bool canRedo,
    @Default(FriendOpponent()) Opponent opponent,
  }) = _GameViewState;
}
